  "command": "cd /mnt/session/uploads; python3 - <<'EOF'
import json,collections
c500=collections.Counter(); dbq=collections.Counter(); msgs=collections.Counter(); ex={}
for line in open('app.log'):
    try: r=json.loads(line)
    except: continue
    if r.get('service')!='checkout': continue
    m=r['ts'][:16]
    if r['level']=='ERROR' or r.get('status')==500 or r.get('status_code')==500:
        c500[m]+=1; msgs[r['msg']]+=1; ex.setdefault(r['msg'],r)
    if 'db_query' in r['msg']: dbq[m]+=1
print("checkout errors/min:",sorted(c500.items())[:40])
print("db_query/min:",sorted(dbq.items())[:40])
for k,v in msgs.most_common(10): print(v,k)
for v in list(ex.values())[:4]: print(json.dumps(v))
EOF"
